() => {
  const aside = document.querySelector('aside') || document.querySelector('[class*="sidebar"]') || document.querySelector('nav');
  const results = [];
  if (!aside) return { error: 'no aside found' };
  // 找到侧边栏中所有菜单按钮（分析功能中心区域）
  const buttons = Array.from(aside.querySelectorAll('button'));
  const menuBtns = buttons.filter(b => {
    const t = b.textContent || '';
    return ['智能问答与查询','可视化决策报表','问数报告中心','决策数据看板','灵活查询','数据源与','系统管理','数据源表结构'].some(k => t.includes(k));
  });
  const check = (el, label) => {
    const r = el.getBoundingClientRect();
    const lh = parseFloat(getComputedStyle(el).lineHeight) || 20;
    const lines = Math.round((r.height / lh) * 10) / 10;
    results.push({
      label,
      text: (el.textContent || '').trim().slice(0, 30),
      heightPx: Math.round(r.height),
      lineHeight: lh,
      approxLines: lines,
      singleLine: r.height <= lh * 1.25,
      truncated: el.scrollWidth > el.clientWidth + 1
    });
  };
  menuBtns.forEach(btn => {
    // 遍历按钮内的叶子文本元素
    const walker = document.createTreeWalker(btn, NodeFilter.SHOW_ELEMENT);
    let node;
    const leaves = [];
    while ((node = walker.nextNode())) {
      if (node.children.length === 0 && (node.textContent || '').trim()) leaves.push(node);
    }
    leaves.forEach(el => check(el, btn.textContent.trim().slice(0,12)));
  });
  return { menuBtnCount: menuBtns.length, results };
}
